package br.com.caelum.vraptor.ioc;

import java.util.HashMap;
import java.util.Map;

import br.com.caelum.vraptor.core.InterceptorStack;
import br.com.caelum.vraptor.interceptor.Interceptor;

/**
 * @author 
 * @since 3.1.0
 */
public class Container {

	private final Map<Class<?>, Object> instances = new HashMap<Class<?>, Object>();
	private final Map<Class<?>, Interceptor> interceptors = new HashMap<Class<?>, Interceptor>();

	public <T> T getInstance(Class<T> type) {
		return (T) instances.get(type);
	}

	public <T> void register(Class<T> type, T instance) {
		instances.put(type, instance);
	}

	public <T> void register(Class<T> type, Interceptor interceptor) {
		interceptors.put(type, interceptor);
	}

	public <T> Interceptor getInterceptor(Class<T> type) {
		return interceptors.get(type);
	}

	public <T> void registerInterceptor(Class<T> type, Interceptor interceptor) {
		interceptors.put(type, interceptor);
	}

	public <T> void registerInterceptor(Class<T> type, Interceptor interceptor,
			InterceptorStack stack) {
		InterceptorStack newStack = new InterceptorStack(stack);
		newStack.add(interceptor);
		interceptors.put(type, newStack);
	}
}
