package com.github.khoadn.codeassist.model;

import java.util.HashMap;
import java.util.Map;

import com.github.khoadn.codeassist.model.CodeAssist.CodeAssistBuilder;

public class CodeAssist {
    private final String code;
    private final String assistant;
    private final String user;
    private final String system;
    private final Map<String, String> hints;

    public CodeAssist(String code, String assistant, String user, String system) {
        this.code = code;
        this.assistant = assistant;
        this.user = user;
        this.system = system;
        this.hints = new HashMap<>();
    }

    public String getCode() {
        return code;
    }

    public String getAssistant() {
        return assistant;
    }

    public String getUser() {
        return user;
    }

    public String getSystem() {
        return system;
    }

    public Map<String, String> getHints() {
        return hints;
    }

    public static CodeAssistBuilder builder() {
        return new CodeAssistBuilder();
    }

    public static class CodeAssistBuilder {
        private String code;
        private String assistant;
        private String user;
        private String system;

        public CodeAssistBuilder code(String code) {
            this.code = code;
            return this;
        }

        public CodeAssistBuilder assistant(String assistant) {
            this.assistant = assistant;
            return this;
        }

        public CodeAssistBuilder user(String user) {
            this.user = user;
            return this;
        }

        public CodeAssistBuilder system(String system) {
            this.system = system;
            return this;
        }

        public CodeAssistBuilder hint(String key, String value) {
            this.hints.put(key, value);
            return this;
        }

        public CodeAssist build() {
            return new CodeAssist(code, assistant, user, system);
        }
    }
}
