@Controller
@RequestMapping("/user")
public class UserController {

	@Autowired
	private UserService userService;

	@GetMapping("/register")
	public String register(Model model) {
		model.addAttribute("user", new User());
		return "register";
	}

	@PostMapping("/register")
	public String registerUser(Model model, User user) {
		model.addAttribute("user", user);
		if (!userService.save(user)) {
			model.addAttribute("error", "Viga. Kasutajat ei salvestatud.");
			return "register";
		}
		return "redirect:/user/login";
	}

	@GetMapping("/login")
	public String login(Model model) {
		model.addAttribute("user", new User());
		return "login";
	}

	@PostMapping("/login")
	public String loginUser(Model model, User user, HttpServletRequest request) {
		model.addAttribute("user", user);
		Optional<User> u = userService.findByUsernameAndPassword(user.getUsername(), user.getPassword());
		if (u.isPresent()) {
			HttpSession session = request.getSession();
			session.setAttribute("user", u.get());
			return "redirect:/";
		} else {
			model.addAttribute("error", "Viga. Kasutajat ei leitud.");
			return "login";
		}
	}

