import org.springframework.web.bind.annotation.RestController;

import nl.tudelft.secure.web.service.TokenService;
import nl.tudelft.secure.web.service.TokenStore;

@RestController
public class TokenController {

    @Autowired
    private TokenService tokenService;

    @Autowired
    private TokenStore tokenStore;

    @RequestMapping("/tokens/{token}")
    public void getToken(@PathVariable(value = "token") String token, HttpServletResponse response) throws IOException {
        Map<String, String> tokenHeader = tokenService.readTokenHeader(token);
        if (tokenHeader.get("alg").equals("HS256")) {
            response.getOutputStream().write(tokenStore.get(token).getBytes());
        } else {
            throw new RuntimeException("Unsupported algorithm");
        }
    }
}
