package com.github.bassam.exercism.java.exercises.concept.stringcalculator;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class StringCalculatorTest {
    @Test
    void test_empty_string() {
        assertEquals(0, StringCalculator.add(""));
    }

    @Test
    void test_one_number() {
        assertEquals(1, StringCalculator.add("1"));
    }

    @Test
    void test_two_numbers() {
        assertEquals(3, StringCalculator.add("1,2"));
    }

    @Test
    void test_three_numbers() {
        assertEquals(6, StringCalculator.add("1,2,3"));
    }

    @Test
    void test_negative_number() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> StringCalculator.add("-1"));
        assertEquals("-1", exception.getMessage());
    }

    @Test
    void test_negative_numbers() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> StringCalculator.add("1,-2,3"));
        assertEquals("-2", exception.getMessage());
    }

    @Test
    void test_multiple_negative_numbers() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> StringCalculator.add("1,-2,-3"));
        assertEquals("-2,-3", exception.getMessage());
    }

    @Test
    void test_big_numbers() {
        assertEquals(1000, StringCalculator.add("1,1000"));
    }

    @Test
    void test_big_numbers_with_other_numbers() {
        assertEquals(1001, StringCalculator.add("1,1000,1"));
    }

}
