package fr.umlv.security.jwt;

import java.util.Map;

import com.auth0.jwt.exceptions.JWTVerificationException;
import com.auth0.jwt.interfaces.DecodedJWT;
import com.auth0.jwt.interfaces.JWTVerifier;
import com.auth0.jwt.interfaces.Verification;

import io.javalin.http.Context;
import io.javalin.http.Handler;

public class JWTAuthenticator implements Handler {
    private final JWTVerifier verifier;

    public JWTAuthenticator(JWTVerifier verifier) {
        this.verifier = verifier;
    }

    public JWTAuthenticator(String secret) {
        this(new JWT(secret).verifier());
    }

    @Override
    public void handle(Context ctx) {
        try {
            verifier.verify(ctx.header("Authorization").split(" ")[1]);
        } catch (JWTVerificationException e) {
            ctx.status(401);
            return;
        }
        ctx.next();
    }
}
