package edu.cmu.cs.compilers.hw2.ast;

import java.util.ArrayList;
import java.util.List;

import edu.cmu.cs.compilers.hw2.visitor.Visitor;

public abstract class ASTNode {
    public abstract <T> T accept(Visitor<T> v);
    public abstract List<ASTNode> getChildren();
    public abstract String toString();
    public abstract String toPrettyString();
    public abstract String toPrettyString(int indent);
    public abstract String toPrettyString(int indent, String indentStr);
    public abstract String toPrettyString(int indent, String indentStr, String separator);
    public abstract String toPrettyString(int indent, String indentStr, String separator, String lastSeparator);

    public static List<ASTNode> getChildren(ASTNode node) {
        List<ASTNode> children = new ArrayList<>();
        if (node == null) {
            return children;
        }
        children.add(node);
        children.addAll(node.getChildren());
        return children;
    }

    public static String getChildrenString(ASTNode node) {
        List<ASTNode> children = getChildren(node);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < children.size(); i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(children.get(i).toString());
        }
        return sb.toString();
    }
}
