    while (entry!= null) {
        String filePath = destDir + File.separator + entry.getName();
        if (!entry.isDirectory()) {
            // membuat direktori jika tidak ada
            File dir = new File(filePath).getParentFile();
            dir.mkdirs();
            // membuat file baru
            File destFile = new File(filePath);
