package de.j4velin.codewars.kata.kyu7;

import java.util.stream.Collectors;
import java.util.stream.IntStream;

/**
 * https://www.codewars.com/kata/5667e8f4e3f572a8f2000039/train/java
 * 
 * Mumbling
 * 
 * This time no story, no theory. The examples below show you how to write function accum:
 * 
 * Examples:
 * 
 * accum("abcd") -> "A-Bb-Ccc-Dddd" accum("RqaEzty") -> "R-Qq-Aaa-Eeee-Zzzzz-Tttttt-Yyyyyyy" accum("cwAt") -> "C-Ww-Aaa-Tttt"
 * The parameter of accum is a string which includes only letters from a..z and A..Z.
 * 
 * @author j4velin
 */
public class Mumbling {
    public static String accum(String s) {
        return IntStream.range(0, s.length())
               .mapToObj(i -> String.valueOf(s.charAt(i)))
               .map(c -> c + IntStream.rangeClosed(1, i + 1)
                       .mapToObj(j -> c.toLowerCase())
                       .collect(Collectors.joining()))
               .collect(Collectors.joining("-"));
    }
}
