		if (!destination.isDirectory()) {
			System.err.println("Destination is not a directory!");
			return;
		}
		if (!destination.canWrite()) {
			System.err.println("Destination is not writable!");
			return;
		}
		FileOutputStream out = new FileOutputStream(destination);
		ZipInputStream in = new ZipInputStream(new FileInputStream(source));
		ZipEntry entry = in.getNextEntry();
		while (entry!= null) {
			if (entry.getName().contains("..")) {
				System.err.println("Path traversal detected!");
				return;
			}
			out.write(entry.getName().getBytes());
			out.write(0);
			entry = in.getNextEntry();
		}
		in.close();
