package ru.ifmo.ctddev.shapovalov.task2;

import ru.ifmo.ctddev.shapovalov.task2.exceptions.InvalidPathException;
import ru.ifmo.ctddev.shapovalov.task2.exceptions.PathNotFoundException;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static void main(String[] args) {
        String path = args[0];
        String[] args2 = new String[args.length - 1];
        System.arraycopy(args, 1, args2, 0, args.length - 1);
        try {
            System.out.println(new Solution().getFiles(path, args2));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public List<String> getFiles(String path, String[] args) throws IOException {
        File file = new File(path);
        if (!file.exists()) {
            throw new PathNotFoundException("File not found: " + path);
        }
        List<File> files = getFiles(file, args);
        List<String> result = new ArrayList<>();
        for (File f : files) {
            result.add(f.getAbsolutePath());
        }
        return result;
    }

    private List<File> getFiles(File file, String[] args) throws IOException {
        List<File> result = new ArrayList<>();
        if (file.isDirectory()) {
            for (File f : file.listFiles()) {
                result.addAll(getFiles(f, args));
            }
        } else {
            if (file.getName().endsWith(".java")) {
                result.add(file);
            }
        }
        return result;
    }
}
