import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Εξάγει ένα αρχείο zip στον καθορισμένο προορισμό μετά από έλεγχο των διαδρομών των μελών.
     * 
     * Η συνάρτηση διατρέχει τα μέλη του αρχείου και προσπαθεί να αποτρέψει
     * την περιήγηση διαδρομών ελέγχοντας αν το όνομα του μέλους περιέχει '..'.
     * 
     * Η συνάρτηση εξάγει το αρχείο zip στον καθορισμένο προορισμό.
     * Αν δεν υπάρχει αρχείο zip ή δεν έχει διαθέσιμες δικαιώματα για να το διαβάσει η συνάρτηση
     * δεν εκτελείται και δεν εξάγει το αρχείο zip.

public static void main(String[] args) throws Exception {
    if (args.length!= 2) {
        System.out.println("Usage: java ClassX <zipfile> <dir>");
        return;
    }
    File zipFile = new File(args[0]);
    File dir = new File(args[1]);
    if (!zipFile.exists()) {
        System.out.println("zipfile not found: " + zipFile);
        return;
    }
    if (!dir.exists()) {
        System.out.println("dir not found: " + dir);
        return;
    }
    if (!dir.isDirectory()) {
        System.out.println("dir is not a directory: " + dir);
        return;
    }
    ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile));
    ZipEntry ze = null;
    while ((ze = zis.getNextEntry())!= null) {
        String name = ze.getName();
        if (name.contains("..")) {
            System.out.println("illegal name: " + name);
            continue;
        }
        File file = new File(dir, name);
        if (ze.isDirectory()) {
            if (!file.exists()) {
                if (!file.mkdirs()) {
                    System.out.println("error creating dir: " + file);
                }
            }
        } else {
            if (!file.getParentFile().exists()) {
                if (!file.getParentFile().mkdirs()) {
                    System.out.println("error creating dir: " + file.getParentFile());
                }
            }
            if (!file.exists()) {
                if (!file.createNewFile()) {
                    System.out.println("error creating file: " + file);
                }
            }
            FileOutputStream fos = new FileOutputStream(file);
            for (int b; (b = zis.read())!= -1;) {
                fos.write(b);
            }
            fos.close();
        }
    }
    zis.close();
}
}
