        String member = args[0];
        String archive = args[1];
        String output = args[2];
        if (member.startsWith("/")) {
            System.out.println("Invalid member name: " + member);
            return;
        }
        File archiveFile = new File(archive);
        if (!archiveFile.exists()) {
            System.out.println("Invalid archive: " + archive);
            return;
        }
        File outputDir = new File(output);
        if (!outputDir.exists()) {
            if (!outputDir.mkdirs()) {
                System.out.println("Could not create output directory: " + output);
                return;
            }
        }
        if (!outputDir.isDirectory()) {
            System.out.println("Output is not a directory: " + output);
            return;
        }
        File memberFile = new File(output, member);
        if (!memberFile.getParentFile().exists()) {
            if (!memberFile.getParentFile().mkdirs()) {
                System.out.println("Could not create output directory: " + memberFile.getParent());
                return;
            }
        }
        if (memberFile.exists()) {
            System.out.println("Output file already exists: " + memberFile);
            return;
        }
        boolean success = memberFile.createNewFile();
        if (!success) {
            System.out.println("Could not create output file: " + memberFile);
            return;
        }
        System.out.println("Extracted: " + member);
    }
