package nl.tudelft.ti2206.assignment.gui;

import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.File;

import javax.swing.JButton;
import javax.swing.JFileChooser;
import javax.swing.JPanel;
import javax.swing.JTextField;

import nl.tudelft.ti2206.assignment.controller.Controller;

/**
 * This class represents a panel for selecting a file.
 * 
 * @author 
 * @version 1.0
 */
public class FileSelectionPanel extends JPanel {

	private static final long serialVersionUID = 1L;

	private JTextField pathField;
	private JButton openButton;
	private Controller controller;

	/**
	 * Creates a new FileSelectionPanel.
	 * 
	 * @param controller
	 *            The controller.
	 */
	public FileSelectionPanel(Controller controller) {
		super();

		this.controller = controller;

		pathField = new JTextField();
		pathField.setEditable(false);

		openButton = new JButton("Open");
		openButton.addActionListener(new ActionListener() {

			@Override
			public void actionPerformed(ActionEvent e) {
				openFile();
			}
		});

		this.add(pathField);
		this.add(openButton);
	}

	/**
	 * Opens a file chooser and sets the selected file as the current file.
	 */
	private void openFile() {
		JFileChooser chooser = new JFileChooser();
		chooser.setFileSelectionMode(JFileChooser.FILES_ONLY);
		int returnVal = chooser.showOpenDialog(this);
		if (returnVal == JFileChooser.APPROVE_OPTION) {
			File file = chooser.getSelectedFile();
			controller.setCurrentFile(file);
			pathField.setText(file.getAbsolutePath());
		}
	}
}
