package com.github.j3rvis.codewars.solutions.kyu8;

import java.util.Arrays;
import java.util.stream.Collectors;

/**
 * @author j3rvis
 */
public class SortTheOdd {

    public static int[] sortArray(int[] array) {
        return Arrays.stream(array).filter(i -> i % 2!= 0).sorted().mapToInt(i -> i).toArray();
    }

    public static int[] sortArray2(int[] array) {
        return Arrays.stream(array).boxed().sorted((o1, o2) -> o1 % 2!= o2 % 2? o1 % 2 - o2 % 2 : o1 - o2).mapToInt(i -> i).toArray();
    }

    public static int[] sortArray3(int[] array) {
        return Arrays.stream(array).boxed().sorted((o1, o2) -> o1 % 2!= o2 % 2? o1 % 2 - o2 % 2 : o1 - o2).mapToInt(i -> i).toArray();
    }

}
