public class FindTheSmallestIntegerInTheArray extends KataTest {

    public static void main(String[] args) {
        new FindTheSmallestIntegerInTheArray().test();
    }

    public int findSmallestInt(int[] args) {
        int smallest = args[0];
        for (int i = 1; i < args.length; i++) {
            if (args[i] < smallest) {
                smallest = args[i];
            }
        }
        return smallest;
    }
}
