    /**
     * Creates a new Mailcap from the given file.
     *
     * @param file the file to read from
     * @return a new Mailcap
     */
    public static Mailcap fromFile(String file) {
        Map<String, String> entries = new HashMap<>();
        for (String line : StringUtils.readLines(file)) {
            String[] parts = line.split(";");
            if (parts.length >= 2 && parts[0].contains("=")) {
                String key = parts[0].split("=")[0];
                String value = parts[1];
                entries.put(key, value);
            }
        }
        return new Mailcap(entries);
    }

    /**
     * Returns the mime_type for the given file.
     *
     * @param file the file to find the mime_type for
     * @return the mime_type of the file
     */
    public String findMatch(String file) {
        for (Map.Entry<String, String> entry : entries.entrySet()) {
            String mime_type = entry.getKey();
            String command = entry.getValue();

            // Check for file extension
            if (mime_type.contains(".")) {
                String[] parts = mime_type.split("\\.");
                String extension = parts[parts.length - 1];
                if (file.endsWith(extension)) {
                    return command;
                }
            }

            // Check for mime_type
            else if (file.startsWith(mime_type)) {
                return command;
            }
        }

        return null;
    }

