package ir.ac.sbu.t2.test;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

import static ir.ac.sbu.t2.test.Test2.Result.*;

public class Test2 {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = reader.readLine())!= null) {
            if (line.isEmpty()) {
                break;
            }
            try {
                System.out.println(evaluate(line));
            } catch (Exception e) {
                System.out.println(ERROR);
            }
        }
    }

    public static Result evaluate(String input) throws Exception {
        String[] tokens = input.split("\\s+");
        if (tokens.length!= 3) {
            throw new Exception();
        }
        String operator = tokens[1];
        if (!operator.equals("+") &&!operator.equals("-") &&!operator.equals("*") &&!operator.equals("/")) {
            throw new Exception();
        }
        int a = Integer.parseInt(tokens[0]);
        int b = Integer.parseInt(tokens[2]);
        switch (operator) {
            case "+":
                return new Result(a + b);
            case "-":
                return new Result(a - b);
            case "*":
                return new Result(a * b);
            case "/":
                return new Result(a / b);
            default:
                throw new Exception();
        }
    }

    public static class Result {
        public final int value;
        public Result(int value) {
            this.value = value;
        }

        @Override
        public String toString() {
            return String.valueOf(value);
        }

        public static final Result ERROR = new Result(0);
    }
}
