        final Scanner in = new Scanner(System.in);
        final int surfaceN = in.nextInt();
        final int[] h = new int[surfaceN];
        for (int i = 0; i < surfaceN; i++) {
            h[i] = in.nextInt();
        }
        in.close();
        int current = 0;
        int max = 0;
        for (int i = 0; i < surfaceN; i++) {
