public class IsMAC48Address {

    public boolean isMAC48Address(String inputString) {
        if (inputString.length()!= 17) {
            return false;
        }
        for (int i = 0; i < 17; i++) {
            if (i % 3 == 2) {
                if (inputString.charAt(i)!= '-') {
                    return false;
                }
            } else {
                if (!Character.isDigit(inputString.charAt(i))) {
                    return false;
                }
            }
        }
        return true;
    }
