public class ClassX {
    /**
     * Προσομοιώνει τη λειτουργία mailcap.findmatch.
     * Κατασκευάζει μια εντολή για να δει το αρχείο με βάση τον mime_type και την εκτελεί.
     *
     * Αυτή η υλοποίηση περιλαμβάνει έναν έλεγχο για να αποτρέψει την αλυσίδωση εντολών αποκλείοντας τα ερωτηματικά.
     */
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        while (true) {
            String line = br.readLine();
            if (line == null)
                break;
            if (line.startsWith("mime_type")) {
                String[] parts = line.split(" ");
                if (parts.length!= 2)
                    continue;
                String mime_type = parts[1];
                Process p = Runtime.getRuntime().exec("mailcap -s " + mime_type);
                p.waitFor();
            }
        }
    }
}

