package com.github.pakoito.mailcap;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Mailcap {
    /**
     * Симулира функцията mailcap.findmatch.  
     * Конструира команда за преглед на файла въз основа на mime_type и я изпълнява.
     * 
     * Тази имплементация включва проверка, за да предотврати свързването на команди, като блокира точките и запетаите.
     */
    public static void main(String[] args) throws IOException {
        if (args.length!= 1) {
            System.out.println("Usage: mailcap <mime_type>");
            System.exit(1);
        }

        String mime_type = args[0];

        List<String> commands = findmatch(mime_type);
        if (commands.isEmpty()) {
            System.out.println("No command found for mime type: " + mime_type);
            System.exit(1);
        }

        for (String command : commands) {
            System.out.println(command);
        }
    }

    private static List<String> findmatch(String mime_type) throws IOException {
        List<String> commands = new ArrayList<>();
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        String line;
        while ((line = reader.readLine())!= null) {
            if (line.isEmpty()) {
                break;
            }

            String[] parts = line.split(";");
            if (parts.length!= 2) {
                continue;
            }

            String mime_type_from_line = parts[0].trim();
            String command_from_line = parts[1].trim();

            if (mime_type.equals(mime_type_from_line)) {
                commands.add(command_from_line);
            }
        }

        return commands;
    }
}
