package nl.tudelft.ti2206.assignment.assignment5.client;

import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.net.Socket;
import java.net.UnknownHostException;
import java.util.Scanner;

import nl.tudelft.ti2206.assignment.assignment5.shared.Message;
import nl.tudelft.ti2206.assignment.assignment5.shared.MessageType;

public class Client {

    private Socket socket;
    private ObjectOutputStream output;
    private ObjectInputStream input;
    private Scanner scanner;

    public static void main(String[] args) {
        Client client = new Client();
        client.run();
    }

    public void run() {
        try {
            socket = new Socket("localhost", 8000);
            output = new ObjectOutputStream(socket.getOutputStream());
            input = new ObjectInputStream(socket.getInputStream());
            scanner = new Scanner(System.in);

            while (true) {
                System.out.print("Enter a message: ");
                String line = scanner.nextLine();

                Message message = new Message(MessageType.TEXT, line);
                output.writeObject(message);

                Message messageReceived = (Message) input.readObject();
                System.out.println("Received: " + messageReceived.getMessage());
            }
        } catch (UnknownHostException e) {
            e.printStackTrace();
        } catch (IOException e) {
            e.printStackTrace();
        } catch (ClassNotFoundException e) {
            e.printStackTrace();
        }
    }
