package com.github.joshuaeason.codefights.arcade.intro.level5;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Given a rectangular matrix of characters, add a border of asterisks(*) to it.
 *
 * Example
 *
 * For
 *
 * picture = ["abc",
 *             "ded"]
 *
 * the output should be
 *
 * addBorder(picture) = ["*****",
 *                       "*abc*",
 *                       "*ded*",
 *                       "*****"]
 */
public class AddBorder {

  public static List<String> addBorder(String[] picture) {
    int length = picture[0].length();
    String border = String.join("", Collections.nCopies(length + 2, "*"));
    String[] result = new String[picture.length + 2];
    result[0] = border;
    result[result.length - 1] = border;
    for (int i = 0; i < picture.length; i++) {
      result[i + 1] = "*" + picture[i] + "*";
    }
    return Arrays.asList(result);
  }
}
