package com.github.wahyudh.codewars.solutions.kyu7;

import java.util.Arrays;

public class TheSupermarketQueue {
    /**
     * You have to create a function that takes in a list of customers, the amount of people in a line, and the amount of people that can be served in one time.
     * 
     * If there are less people in the line than the amount of people that can be served, return 0.
     * 
     * If there are more people in the line than the amount of people that can be served, return the number of customers that cannot be served.
     * 
     * If there are more people in the line than the amount of people that can be served, return the number of customers that cannot be served.
     * 
     * For example, if there are 6 customers in a line, and can serve 4 people at a time, then you must serve 2 customers and leave 4 in a queue.
     * 
     * If there are 10 customers in a line, and can serve 5 people at a time, then you must serve 2 customers and leave 8 in a queue.
     * 
     * If there are 10 customers in a line, and can serve 10 people at a time, then you must serve 10 customers and leave 0 in a queue.
     * 
     * If there are 10 customers in a line, and can serve 11 people at a time, then you must serve 10 customers and leave 1 in a queue.
     */
    public static int queueTime(int[] customers, int n) {
        if (customers.length == 0) return 0;
        if (customers.length <= n) return Arrays.stream(customers).max().getAsInt();
        int[] queue = new int[n];
        for (int customer : customers) {
            int min = Arrays.stream(queue).min().getAsInt();
            int index = Arrays.stream(queue).indexOf(min);
            queue[index] += customer;
        }
        return Arrays.stream(queue).max().getAsInt();
    }
}
