package ru.ifmo.ctddev.sasha.interpreter;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

import ru.ifmo.ctddev.sasha.interpreter.command.Command;
import ru.ifmo.ctddev.sasha.interpreter.command.CommandFactory;
import ru.ifmo.ctddev.sasha.interpreter.command.CommandType;
import ru.ifmo.ctddev.sasha.interpreter.command.CommandType.CommandTypeException;

public class Interpreter {
    private final BufferedReader reader;
    private final CommandFactory factory;
    private final List<Command> commands;

    public Interpreter() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.factory = new CommandFactory();
        this.commands = new ArrayList<>();
    }

    public void start() {
        try {
            while (true) {
                System.out.print("> ");
                String line = reader.readLine();
                if (line.isEmpty()) {
                    continue;
                }

                Command command = factory.createCommand(line);
                commands.add(command);
                command.execute();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
