package com.github.michaelwolfenden.codewars.kata.8kyu;

import java.util.Arrays;

/**
 * Counting sheep...
 * 
 * <p>
 * Consider an array of sheep where some sheep may be missing from their place. We need a function that counts the number of sheep present in the array (true means present).
 * 
 * <p>
 * For example,
 * 
 * <p>
 * [true,  true,  true,  false,
 * true,  true,  true,  true,
 * true,  false, true,  false,
 * true,  false, false, true,
 * true,  true,  true,  true,
 * false, false, true,  true]
 * 
 * <p>
 * The correct answer would be 17.
 * 
 * <p>
 * Hint: Don't forget to check for bad values like null/undefined
 * 
 * <p>
 * <a href="https://www.codewars.com/kata/54edbc7200b811e956000556/train/java">https://www.codewars.com/kata/54edbc7200b811e956000556/train/java</a>
 */
public class CountingSheep {

    public static int countSheeps(Boolean[] arrayOfSheeps) {
        if (arrayOfSheeps == null) {
            return 0;
        }

        return (int) Arrays.stream(arrayOfSheeps).filter(Boolean::booleanValue).count();
    }
}
