package com.github.codeblanche.codewars.kata.8kyu;

import java.util.List;
import java.util.stream.Collectors;

public class CountingSheep {
    /**
     * https://www.codewars.com/kata/54edbc7200b811e956000556
     *
     * Given a non-empty array of integers, return the result of multiplying the values together in order. Example:
     * [1, 2, 3, 4] => 1 * 2 * 3 * 4 = 24
     *
     * @param sheep
     * @return
     */
    public static int countSheeps(boolean[] sheep) {
        return (int) sheep.stream().filter(x -> x).count();
    }

    public static String countSheeps(List<Boolean> sheep) {
        return sheep.stream().filter(x -> x).map(String::valueOf).collect(Collectors.joining(" * "));
    }
}
