package com.github.robin.codereview.model;

import java.util.ArrayList;
import java.util.List;

public class CodeReview {

    private List<Review> reviews = new ArrayList<>();

    public void addReview(Review review) {
        reviews.add(review);
    }

    public List<Review> getReviews() {
        return reviews;
    }

    public void setReviews(List<Review> reviews) {
        this.reviews = reviews;
    }

    public int getNumberOfReviews() {
        return reviews.size();
    }

    public int getNumberOfComments() {
        return reviews.stream().mapToInt(Review::getNumberOfComments).sum();
    }

    public int getNumberOfCommentsOf(ReviewType reviewType) {
        return (int) reviews.stream().filter(review -> review.getReviewType().equals(reviewType)).mapToInt(Review::getNumberOfComments).sum();
    }

    public int getNumberOfCommentsOf(String reviewType) {
        return getNumberOfCommentsOf(ReviewType.valueOf(reviewType));
    }

    public int getNumberOfAnswers() {
        return reviews.stream().mapToInt(Review::getNumberOfAnswers).sum();
    }

    public int getNumberOfAnswersOf(ReviewType reviewType) {
        return (int) reviews.stream().filter(review -> review.getReviewType().equals(reviewType)).mapToInt(Review::getNumberOfAnswers).sum();
    }

    public int getNumberOfAnswersOf(String reviewType) {
        return getNumberOfAnswersOf(ReviewType.valueOf(reviewType));
    }

    public int getNumberOfAnswersOf(ReviewType reviewType, boolean isAnswered) {
        return (int) reviews.stream().filter(review -> review.getReviewType().equals(reviewType)).filter(review -> review.isAnswered() == isAnswered).mapToInt(Review::getNumberOfAnswers).sum();
    }

    public int getNumberOfAnswersOf(String reviewType, boolean isAnswered) {
        return getNumberOfAnswersOf(ReviewType.valueOf(reviewType), isAnswered);
    }

    public int getNumberOfAnswersOf(String reviewType, String isAnswered) {
        return getNumberOfAnswersOf(ReviewType.valueOf(reviewType), Boolean.valueOf(isAnswered));

}
