public class JavaHelper {
    private static List<String> getTags(String code) {
        List<String> tags = new ArrayList<>();
        int index = 0;
        while (index!= -1) {
            index = code.indexOf("<|", index);
            if (index!= -1) {
                int endIndex = code.indexOf("|>", index);
                if (endIndex!= -1) {
                    tags.add(code.substring(index + 2, endIndex));
                    index = endIndex + 2;
                } else {
                    index++;
                }
            }
        }
        return tags;
    }

    public static String getCodeWithoutTags(String code) {
        List<String> tags = getTags(code);
        for (String tag : tags) {
            code = code.replace("<|" + tag + "|>", "");
        }
        return code;
    }

    public static String getCodeWithTags(String code) {
        List<String> tags = getTags(code);
        for (String tag : tags) {
            code = code.replace("<|" + tag + "|>", "");
        }
        return code;
    }
}
