public class VariableNameVisitor extends VoidVisitorAdapter<Set<String>> {

    private static final Set<String> VARIABLE_NAMES = new HashSet<>();

    @Override
    public void visit(final VariableDeclarationExpr n, final Set<String> arg) {
        n.getVariables().forEach(v -> VARIABLE_NAMES.add(v.getNameAsString()));
    }

    @Override
    public void visit(final VariableDeclarator n, final Set<String> arg) {
        VARIABLE_NAMES.add(n.getNameAsString());
    }

    @Override
    public void visit(final BlockStmt n, final Set<String> arg) {
        n.getStatements().forEach(s -> s.accept(this, arg));
