public class FindTheStrayNumber {

    public static int stray(final int[] numbers) {
        final List<Integer> list = Arrays.asList(numbers);
        final int n = list.stream().filter(i -> list.stream().filter(j -> j!= i).count() == 1).findFirst().get();
        return n;
    }

