public class TemplateBuilder {

    private final Template template;

    private final List<String> imports = new ArrayList<>();

    private final List<String> lines = new ArrayList<>();

    public TemplateBuilder(String template) {
        this.template = new Template(template);
    }

    public TemplateBuilder addImport(String importName) {
        imports.add(importName);
        return this;
    }

    public TemplateBuilder addLine(String line) {
        lines.add(line);
        return this;
    }

    public TemplateBuilder addLine(String... lines) {
        for (String line : lines) {
            addLine(line);
        }
        return this;
    }

    public Template build() {
        template.getImports().addAll(imports);
        template.getImports().addAll(lines);
        return template;
    }

    public static TemplateBuilder fromTemplate(Template template) {
        TemplateBuilder builder = new TemplateBuilder(template.getTemplate());
        builder.imports.addAll(template.getImports());
