public class ClassX {
    /**
     * Menghasilkan sebuah template yang mencakup input pengguna.
     * 
     * Fungsi ini berusaha untuk membersihkan input dengan memblokir pembatas variabel Jinja2.
     */
    public static String sanitize(String input) {
        // Membuat array yang berisi karakter yang akan diblokir
        String[] banned = new String[] {
            "<!--",
            "-->",
            "<%",
            "%>",
            "<#",
            "#>",
            "<@",
            "@>",
            "<|",
            "|>",
            "<#=",
            "=#>",
            "<#--",
            "--#>",
            "<#?php",
            "php>",
            "<#?="
        };

        // Mengubah input menjadi array karakter
        String[] inputChars = input.split("");

        // Mengubah input menjadi string baru
        String cleanInput = "";

        // Melakukan pengecekan setiap karakter pada input
        for (String c : inputChars) {
            // Jika karakter tidak ada dalam array banned, maka karakter tersebut akan dimasukkan ke string baru
            if (!Arrays.asList(banned).contains(c)) {
                cleanInput += c;
            }
        }

        // Menghasilkan string baru
        return cleanInput;
    }
}
