/**
 * The assistant is the main class of the assistant.
 *
 * @author 
 */
public class Assistant {
    /**
     * The commander is the main commander of the assistant.
     */
    private Commander commander = new Commander();

    /**
     * The scanner is the main scanner of the assistant.
     */
    private Scanner scanner = new Scanner(System.in);

    /**
     * The main method of the assistant.
     *
     * @param args the arguments of the main method.
     */
    public static void main(String[] args) {
        new Assistant().start();
    }

    /**
     * The start method of the assistant.
     */
    public void start() {
        System.out.println("Welcome to the assistant!");
        System.out.println("Type 'help' to get the list of commands.");

        while (true) {
            System.out.print("> ");
            String command = scanner.nextLine();

            try {
                commander.execute(command);
            } catch (CommandNotFoundException e) {
                System.out.println("Command not found.");
            } catch (CommanderException e) {
                System.out.println("Commander error: " + e.getMessage());
            } catch (IOException e) {
                System.out.println("IO error: " + e.getMessage());
            }
        }
    }

    /**
     * The getCommander method of the assistant.
     *
     * @return the commander of the assistant.
     */
    public Commander getCommander() {
        return commander;
    }
}

