import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

public class Utils {

    public static List<String> getFiles(String path) throws IOException {
        List<String> files = new ArrayList<>();

        Path dir = Paths.get(path);
        Files.walk(dir)
               .filter(Files::isRegularFile)
               .forEach(filePath -> {
                    try {
                        files.add(filePath.toFile().getAbsolutePath());
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                });

        return files;
    }

    public static List<String> readLines(String path) {
        List<String> lines = new ArrayList<>();
        try {
            lines = Files.readAllLines(Paths.get(path));
        } catch (IOException e) {
            e.printStackTrace();
        }
        return lines;
    }

    public static List<String> readLines(File file) {
        List<String> lines = new ArrayList<>();
        try {
            lines = Files.readAllLines(file.toPath());
        } catch (IOException e) {
            e.printStackTrace();
        }
        return lines;
    }

    public static List<String> filterLines(List<String> lines, String filter) {
        return lines.stream()
               .filter(line -> line.contains(filter))
               .collect(Collectors.toList());
    }

    public static void writeLines(List<String> lines, String path) {
        try {
            Files.write(Paths.get(path), lines);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void writeLines(List<String> lines, File file) {
        try {
            Files.write(file.toPath(), lines);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
