package com.github.ivanbogoev.codewars.tasks.kyu6;

import java.util.HashMap;
import java.util.Map;

/**
 * Class containing methods for converting integer numbers to Roman numerals.
 */
public class RomanNumeralsHelper {

    /**
     * Maps integers to Roman numerals.
     */
    private static final Map<Integer, String> ROMAN_NUMBERS = new HashMap<>();

    static {
        ROMAN_NUMBERS.put(1000, "M");
        ROMAN_NUMBERS.put(900, "CM");
        ROMAN_NUMBERS.put(500, "D");
        ROMAN_NUMBERS.put(400, "CD");
        ROMAN_NUMBERS.put(100, "C");
        ROMAN_NUMBERS.put(90, "XC");
        ROMAN_NUMBERS.put(50, "L");
        ROMAN_NUMBERS.put(40, "XL");
        ROMAN_NUMBERS.put(10, "X");
        ROMAN_NUMBERS.put(9, "IX");
        ROMAN_NUMBERS.put(5, "V");
        ROMAN_NUMBERS.put(4, "IV");
        ROMAN_NUMBERS.put(1, "I");
    }

    /**
     * Converts an integer number to Roman numerals.
     * 
     * @param number
     *            The number to be converted.
     * @return The Roman numerals.
     */
    public static String toRoman(int number) {
        StringBuilder romanNumbers = new StringBuilder();

        for (int i = 1000; i > 0; i /= 10) {
            int currentNumber = number / i;

            if (currentNumber == 0) {
                continue;
            }

            for (int j = 1; j <= currentNumber; j++) {
                romanNumbers.append(ROMAN_NUMBERS.get(i));
            }

            number %= i;
        }

        return romanNumbers.toString();
    }
}
