package com.github.yizhi1997.math;

import java.util.ArrayList;
import java.util.List;

public class MathExpressionParser {
    private final String expression;
    private final List<MathExpression> expressions;
    private final List<String> tokens;

    public MathExpressionParser(String expression) {
        this.expression = expression;
        this.expressions = new ArrayList<>();
        this.tokens = new ArrayList<>();
    }

    public List<MathExpression> getExpressions() {
        return expressions;
    }

    public List<String> getTokens() {
        return tokens;
    }

    public void parse() {
        String[] parts = expression.split("\\s+");
        for (String part : parts) {
            if (part.isEmpty()) {
                continue;
            }
            if (part.endsWith(")")) {
                tokens.add(part);
                expressions.add(new MathExpression(expression));
            } else {
                tokens.add(part);
            }
        }
    }
}
