public class Exercise4 {
    /**
     * Write a program that reads a number and prints the next two numbers in the sequence.
     * The next two numbers in the sequence are generated by the following formula:
     * <pre>
     *     nextNumber = (previousNumber * 2) + 1
     * </pre>
     * For example, if the user enters 3, the program should print "5 11".
     * 
     * <pre>
     *     Input: 3
     *     Output: 5 11
     * </pre>
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int number = scanner.nextInt();
        System.out.println(number + " " + (number * 2 + 1));
    }
}
