package com.github.h0tk3y.codewars.kata.8kyu;

import java.util.stream.IntStream;

/**
 * Sum of positive
 *
 * <p>You get an array of numbers, return the sum of all of the positives ones.
 *
 * <p>Example [1,-4,7,12] => 1 + 7 + 12 = 20
 *
 * <p>Note: if there is nothing to sum, the sum is default to 0.
 *
 * <p>Input: An array of numbers output: The sum of numbers that are positive.
 */
public class SumOfPositive {

  public static int positiveSum(int[] arr) {
    return IntStream.of(arr).filter(n -> n > 0).sum();
  }
}
