package com.github.h0tk3y.codewars.kata.8kyu;

/**
 * Counting sheep...
 *
 * <p>Consider an array of sheep where some sheep may be missing from their place. We need a
 * function that counts the number of sheep present in the array (true means present).
 *
 * <p>For example,
 *
 * <p>[true, true, true, false, true, true, true, true, true, false, true, true, true, true,
 * true, true, false, true, true, true, true, true]
 *
 * <p>The correct answer would be 17.
 *
 * <p>Hint: Don't forget to check for bad values like null/undefined
 */
public class CountingSheep {

  public static int countSheeps(boolean[] arrayOfSheep) {
    return (int)
        java.util.Arrays.stream(arrayOfSheep)
           .filter(s -> s)
           .count();
  }
}
