import com.intellij.openapi.project.Project;
import com.intellij.psi.PsiFile;

public class RunAction extends AnAction {
    @Override
    public void update(AnActionEvent event) {
        Presentation presentation = event.getPresentation();
        presentation.setEnabledAndVisible(true);
        presentation.setText("Run");
        presentation.setDescription("Run");

        Project project = event.getProject();
        if (project == null) {
            presentation.setEnabled(false);
            return;
        }

        PsiFile psiFile = event.getData(LangDataKeys.PSI_FILE);
        if (psiFile == null) {
            presentation.setEnabled(false);
            return;
        }

        Editor editor = event.getData(PlatformDataKeys.EDITOR);
        if (editor == null) {
            presentation.setEnabled(false);
            return;
        }

        ConfigurationContext context = event.getData(CommonDataKeys.CONFIGURATION_CONTEXT);
        if (context == null) {
            presentation.setEnabled(false);
            return;
        }

        RunConfigurationProducer producer = new RunConfigurationProducer();
        if (producer.isConfigurationFromContext(psiFile, editor, context)) {
            presentation.setEnabled(true);
        } else {
            presentation.setEnabled(false);
        }
    }

    @Override
    public void actionPerformed(AnActionEvent event) {

