import ir.ac.sbu.cisc.javabrains.compiler.ast.nodes.expression.operator.BinaryOperator;

public abstract class BinaryExpression extends Expression {
    private final Expression left;
    private final Expression right;
    private final BinaryOperator operator;

    public BinaryExpression(Expression left, Expression right, BinaryOperator operator) {
        this.left = left;
        this.right = right;
        this.operator = operator;
    }

    public Expression getLeft() {
        return left;
    }

    public Expression getRight() {
        return right;
    }

    public BinaryOperator getOperator() {
        return operator;
    }

    @Override
    public String toString() {
        return String.format("%s %s %s", left, operator, right);
    }

    @Override
    public Node accept(NodeVisitor visitor) {
        return visitor.visit(this);
    }
}
