        System.out.println(Arrays.toString(theFlyingCats(5, 10, 5, 10, 30)));
        System.out.println(Arrays.toString(theFlyingCats(10, 10, 10, 10, 30)));
        System.out.println(Arrays.toString(theFlyingCats(10, 10, 10, 10, 10)));
    }

    public static int[] theFlyingCats(int a, int b, int c, int d, int e) {
        List<Integer> list = Arrays.asList(a, b, c, d, e);
        int[] result = new int[5];
        for (int i = 0; i < 5; i++) {
            result[i] = list.get(i) + i;
        }
        return result;
    }
