package com.github.code_warrior.codewarrior.models;

import java.util.ArrayList;
import java.util.List;

import javax.persistence.CascadeType;
import javax.persistence.Column;
import javax.persistence.Entity;
import javax.persistence.GeneratedValue;
import javax.persistence.GenerationType;
import javax.persistence.Id;
import javax.persistence.JoinColumn;
import javax.persistence.JoinTable;
import javax.persistence.ManyToMany;
import javax.persistence.ManyToOne;
import javax.persistence.OneToMany;
import javax.persistence.Table;
import javax.validation.constraints.NotNull;

import com.github.code_warrior.codewarrior.models.enums.Language;

@Entity
@Table(name = "code_warriors")
public class CodeWarrior {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @NotNull
    private String name;

    @NotNull
    private String email;

    @NotNull
    private String password;

    @NotNull
    private Language language;

    @NotNull
    private String code;

    @NotNull
    private String output;

    @NotNull
    private String traceback;

    @NotNull
    private String status;

    @ManyToOne
    @JoinColumn(name = "user_id")
    private User user;

    @OneToMany(mappedBy = "codeWarrior")
    private List<CodeWarriorHistory> codeWarriorHistories = new ArrayList<>();

    @ManyToMany
    @JoinTable(
            name = "code_warrior_history_code_warrior",
            joinColumns = @JoinColumn(name = "code_warrior_id"),
            inverseJoinColumns = @JoinColumn(name = "code_warrior_history_id")
    )
    private List<CodeWarriorHistory> codeWarriorHistoriesFromOther = new ArrayList<>();

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

}

