package vn.edu.hust.cse.k19.exercises.java.basic.string.exercise15;

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String input = scanner.nextLine();
        System.out.println("The length of the string is: " + input.length());
        System.out.println("The string in reverse order is: " + reverse(input));
        System.out.println("The string in uppercase is: " + input.toUpperCase());
        System.out.println("The string in lowercase is: " + input.toLowerCase());
        scanner.close();
    }

    public static String reverse(String input) {
        char[] chars = input.toCharArray();
        for (int i = 0; i < chars.length / 2; i++) {
            char temp = chars[i];
            chars[i] = chars[chars.length - 1 - i];
            chars[chars.length - 1 - i] = temp;
        }
        return new String(chars);
    }
}
