    public void add(V value, String word) {
        Trie<V> current = this;
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (current.children.containsKey(c)) {
                current = current.children.get(c);
            } else {
                Trie<V> next = new Trie<>();
                current.children.put(c, next);
                current = next;
            }
        }
        current.add(value);
    }

    /**
     * Returns the value stored in the Trie.
     *
     * @return The value stored in the Trie.
