     * Checks if a JWT token is valid.
     * 
     * The function will decrypt the token and verify it against the supported algorithms, including HS256 and 'none'.
     */
    public static boolean checkJWT(String token) {
        try {
            // Decode the token
            byte[] decodedToken = Base64.getDecoder().decode(token);
            String decodedString = new String(decodedToken);

            // Split the token into header, payload, and signature
            String[] tokens = decodedString.split("\\.");
            String header = tokens[0];
            String payload = tokens[1];
            String signature = tokens[2];

            // Get the algorithm from the header
            String algorithm = getAlgorithm(header);

            // Verify the signature
            if (algorithm.equals("none")) {
                return true;
            } else if (algorithm.equals("HS256")) {
                // Get the secret from the environment variable
                String secret = System.getenv("SECRET");

                // Verify the signature using HS256
                return verifyHS256(payload, signature, secret);
            } else {
                return false;
            }
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Returns the algorithm from the header.
     */
    private static String getAlgorithm(String header) {
        Map<String, String> headerMap = new HashMap<>();
        String[] headerParts = header.split(",");
        for (String headerPart : headerParts) {
            String[] headerPair = headerPart.split("=");
            headerMap.put(headerPair[0].trim(), headerPair[1].trim());
        }
        return headerMap.get("alg");
    }

    /**
     * Verifies the signature using HS256.
     */
    private static boolean verifyHS256(String payload, String signature, String secret) {
        String expectedSignature = Base64.getEncoder().encodeToString(
            HS256.hmacSha256(payload.getBytes(), secret.getBytes())
        );
        return signature.equals(expectedSignature);
    }
