package it.polito.tdp.borders.model;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.jgrapht.Graphs;
import org.jgrapht.graph.DefaultWeightedEdge;
import org.jgrapht.graph.SimpleWeightedGraph;

import it.polito.tdp.borders.db.BordersDAO;

public class Model {
	private BordersDAO dao;
	private Map<Integer, Country> countryMap;
	private Map<Integer, Border> borderMap;
	private SimpleWeightedGraph<Country, DefaultWeightedEdge> graph;

	public Model() {
		this.dao = new BordersDAO();
		this.countryMap = new HashMap<>();
		this.borderMap = new HashMap<>();
		this.graph = new SimpleWeightedGraph<>(DefaultWeightedEdge.class);
	}

	public void creaGrafo() {
		this.countryMap.clear();
		this.borderMap.clear();
		this.graph.clear();

		List<Country> countries = this.dao.loadAllCountries();
		for (Country c : countries) {
			countryMap.put(c.getCountryId(), c);
		}

		List<Border> borders = this.dao.loadAllBorders();
		for (Border b : borders) {
			borderMap.put(b.getBorderId(), b);
		}

		Graphs.addAllVertices(graph, countryMap.values());

		for (Border b : borderMap.values()) {
			Country source = countryMap.get(b.getSourceCountry());
			Country target = countryMap.get(b.getTargetCountry());
			DefaultWeightedEdge e = graph.addEdge(source, target);
			graph.setEdgeWeight(e, b.getQuantity());
		}
	}

	public List<Country> getCountryList() {
		return new ArrayList<>(countryMap.values());
	}

	public List<Border> getBorderList() {
		return new ArrayList<>(borderMap.

}

