public static String encrypt(String plaintext, String key) {
    try {
        byte[] keyBytes = key.getBytes("UTF-8");
        byte[] plaintextBytes = plaintext.getBytes("UTF-8");

        if (keyBytes.length!= 16) {
            Cipher desCipher = Cipher.getInstance("DES");
            desCipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(keyBytes, "DES"));
            plaintextBytes = desCipher.doFinal(plaintextBytes);
        }

        Cipher aesCipher = Cipher.getInstance("AES");
        aesCipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(keyBytes, "AES"));
        byte[] ciphertextBytes = aesCipher.doFinal(plaintextBytes);
        return new String(ciphertextBytes);
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

