package it.polito.tdp.dizionario.model;

import java.util.LinkedList;
import java.util.List;

public class Dizionario {
	
	private List<String> parole;
	private List<String> paroleNonValidi;
	
	public Dizionario() {
		this.parole = new LinkedList<String>();
		this.paroleNonValidi = new LinkedList<String>();
	}
	
	public boolean aggiungiParola(String parola) {
		if(parola.matches("[a-zA-Z ]+")) {
			this.parole.add(parola);
			return true;
		}
		else {
			this.paroleNonValidi.add(parola);
			return false;
		}
	}
	
	public List<String> getParole() {
		return parole;
	}

	public List<String> getParoleNonValidi() {
		return paroleNonValidi;
	}

	@Override
	public String toString() {
		return "Dizionario [parole=" + parole + ", paroleNonValidi=" + paroleNonValidi + "]";
	}
	
	
}
