package com.github.yannickl.exercism.java.exercises.sumofmultiples;

import java.util.ArrayList;
import java.util.List;

public class SumOfMultiples {
    public static int sum(int[] multiples, int max) {
        List<Integer> multiplesList = new ArrayList<>();
        for (int i = 0; i < multiples.length; i++) {
            for (int j = 1; j < max; j++) {
                if (multiples[i]!= 0 && j % multiples[i] == 0) {
                    multiplesList.add(j);
                }
            }
        }
        int sum = 0;
        for (int i = 0; i < multiplesList.size(); i++) {
            sum += multiplesList.get(i);
        }
        return sum;
    }
}
