package com.github.michael_collier.codewars.java.kyu7;

import java.util.Arrays;
import java.util.Comparator;

/**
 * https://www.codewars.com/kata/5a03b3f6a1c90400bd001765
 *
 * <p>Given a string of numbers separated by spaces, return the largest number.
 *
 * <p>Example:
 *
 * <p>largest("13 27 1000")
 *
 * <p>returns 1000
 *
 * <p>largest("4 67 5 2")
 *
 * <p>returns 67
 *
 * <p>Notes:
 *
 * <p>Numbers can be from 1 to 9.
 *
 * <p>The list of numbers are separated by the spaces.
 *
 * <p>Only one number in the list will be greater than 9.
 *
 * <p>If you need help, here's a <a
 * href="http://www.codewars.com/kata/5a03b3f6a1c90400bd001765/train/java">
 * Java Tutorial</a>
 */
public class AlphabeticalAddition {

  public static String largest(String numbers) {
    String[] split = numbers.split(" ");
    Arrays.sort(split, Comparator.naturalOrder());
    return split[split.length - 1];
  }
}
