package com.github.stefanbirkner.codefights.arcade.intro;

import java.util.Arrays;

public class isLucky {
    public static boolean isLucky(int n) {
        int[] digits = new int[10];
        int digitCount = 0;
        while (n > 0) {
            digits[digitCount++] = n % 10;
            n /= 10;
        }
        Arrays.sort(digits);
        return digits[0] == digits[1] && digits[digitCount - 2] == digits[digitCount - 1];
    }
}
