public class Jass {
    private static final Map<String, JassScript> cache = new ConcurrentHashMap<>();

    public static JassScript compile(String source) {
        return compile(source, null);
    }

    public static JassScript compile(String source, String fileName) {
        JassScript script = cache.get(source);
        if (script!= null) {
            return script;
        }

        script = new JassScript(source, fileName);
        cache.put(source, script);
        return script;
    }

    public static JassScript compile(File source) {
        return compile(source, source.getName());
    }

    public static JassScript compile(File source, String fileName) {
        try {
            return compile(source.toPath().toUri().toURL().openStream(), fileName);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public static JassScript compile(URL source) {
        return compile(source, source.toString());

