     * 
     * Функция пытается очистить входные данные, проверяя на наличие очевидных
     * зловредных имен классов или пакетов (имитируя проверку байтов).
     */
    public static UserData deserialize(String serialized) {
        try {
            String decoded = new String(Base64.getDecoder().decode(serialized));
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decoded.getBytes()));
            return (UserData) ois.readObject();
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Сериализует пользовательские данные в строку, закодированную в base64.
     * 
     * Функция пытается очистить входные данные, проверяя на наличие очевидных
     * зловредных имен классов или пакетов (имитируя проверку байтов).
     */
    public static String serialize(UserData data) {
        try {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(baos);
            oos.writeObject(data);
            oos.flush();
            return new String(Base64.getEncoder().encode(baos.toByteArray()));
        } catch (Exception e) {
