import org.javastandards.assistant.model.command.Command;
import org.javastandards.assistant.model.command.CommandFactory;
import org.javastandards.assistant.model.command.CommandType;

public class Assistant {
    private List<Command> commands;
    private CommandFactory commandFactory;

    public Assistant() {
        this.commands = new ArrayList<>();
        this.commandFactory = new CommandFactory();
    }

    public void addCommand(Command command) {
        this.commands.add(command);
    }

    public void addCommand(CommandType type, String command) {
        Command cmd = this.commandFactory.createCommand(type, command);
        this.commands.add(cmd);
    }

    public List<Command> getCommands() {
        return this.commands;
    }
}
