package org.java_help.user;

import org.java_help.user.User.UserBuilder;

import java.util.Objects;

/**
 * User class.
 *
 * @author 
 * @version 1.0
 * @since 2019-03-26
 */
public class User {
    private String name;
    private String id;
    private String email;

    private User() {
    }

    public String getName() {
        return name;
    }

    public String getId() {
        return id;
    }

    public String getEmail() {
        return email;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        User user = (User) o;
        return Objects.equals(name, user.name) &&
                Objects.equals(id, user.id) &&
                Objects.equals(email, user.email);
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, id, email);
    }

    @Override
    public String toString() {
        return "User{" +
                "name='" + name + '\'' +
                ", id='" + id + '\'' +
                ", email='" + email + '\'' +
                '}';
    }

    /**
     * User builder class.
     */
    public static class UserBuilder {
        private String name;
        private String id;
        private String email;

        public UserBuilder() {
        }

        public UserBuilder name(String name) {
            this.name = name;
            return this;
        }

        public UserBuilder id(String id) {
            this.id = id;
            return this;
        }

        public UserBuilder email(String email) {
            this.email = email;
            return this;
        }

        public User build() {
            User user = new User();
            user.name = this.name;
            user.id = this.id;
            user.email = this.email;
            return user;
        }
    }
}
