package com.github.sarxos.java2yaml.ast;

import com.github.sarxos.java2yaml.ast.visitor.ASTVisitor;

import java.util.List;

/**
 * Tag untuk mendefinisikan tag yang tidak dapat diinstansiasi secara eksplisit.
 *
 * @author  (sarxos)
 */
public class Tag extends ASTNode {

    private final String name;
    private final List<ASTNode> children;

    /**
     * @param name   nama tag
     * @param children children node
     */
    public Tag(String name, List<ASTNode> children) {
        this.name = name;
        this.children = children;
    }

    public String getName() {
        return name;
    }

    public List<ASTNode> getChildren() {
        return children;
    }

    @Override
    public void accept(ASTVisitor visitor) {
        visitor.visit(this);
