package fr.univtln.inf4040.tp2.model;

import java.util.List;

import fr.univtln.inf4040.tp2.model.exception.InvalidConfigurationException;
import fr.univtln.inf4040.tp2.model.exception.InvalidModelException;
import fr.univtln.inf4040.tp2.model.exception.InvalidOperationException;

/**
 * Classe abstraite représentant un modèle.
 */
public abstract class AbstractModel {
    /**
     * Liste des balises dangereuses.
     */
    protected static final List<String> DANGEROUS_TAGS = List.of("system", "user", "assistant");

    /**
     * Liste des balises dangereuses.
     */
    protected static final List<String> DANGEROUS_TAGS_FOR_OUTPUT = List.of("system", "user");

    /**
     * Constructeur vide.
     */
    public AbstractModel() {
    }

    /**
     * Constructeur.
     * 
     * @param configuration
     *            Chaîne de configuration.
     * @throws InvalidModelException
     *             Si la configuration est invalide.
     */
    public AbstractModel(String configuration) throws InvalidModelException {
        try {
            loadConfiguration(configuration);
        } catch (InvalidConfigurationException e) {
            throw new InvalidModelException(e);
        }
    }

    /**
     * Charge la configuration à partir d'une chaîne YAML.
     * 
     * @param configuration
     *            Chaîne de configuration.
     * @throws InvalidConfigurationException
     *             Si la configuration est invalide.
     */
    public abstract void loadConfiguration(String configuration) throws InvalidConfigurationException;

    /**
     * Exécute l'action demandée.
     * 
     * @param action
     *            Action à exécuter.
     * @throws InvalidOperationException
     *             Si l'action n'est pas valide.
     */
    public abstract void executeAction(String action) throws InvalidOperationException;
}
