package com.github.kostyan.koding.server;

import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashMap;
import java.util.Map;

import com.github.kostyan.koding.Constants;
import com.github.kostyan.koding.server.handlers.Handler;
import com.github.kostyan.koding.server.handlers.HandlerFactory;

public class Server {

    private final Map<String, Handler> handlers;

    public Server() {
        this.handlers = new HashMap<>();
        this.handlers.put(Constants.USER_HANDLER, new HandlerFactory().getUserHandler());
        this.handlers.put(Constants.SYSTEM_HANDLER, new HandlerFactory().getSystemHandler());
        this.handlers.put(Constants.ASSISTANT_HANDLER, new HandlerFactory().getAssistantHandler());
    }

    public void start() {
        try (ServerSocket serverSocket = new ServerSocket(8080)) {
            while (true) {
                Socket socket = serverSocket.accept();
                new Thread(new ServerThread(socket, handlers)).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

}
