    /**
     * 1. 请使用多态的思想，将方法print改造为一个通用的print方法，使其能打印任何类型的对象。
     * 2. 请使用多态的思想，将方法printArray改造为一个通用的printArray方法，使其能打印任何类型的数组。
     *
     * <p>例如，对于传入的字符串数组["a", "b", "c"]，打印结果应当是
     *
     * <p>a
     * b
     * c
     *
     * <p>对于传入的int数组[1, 2, 3]，打印结果应当是
     *
     * <p>1
     * 2
     * 3
     *
     * <p>请继续使用多态的思想，完成本题剩余的两个方法。
     */
    public static void print(Object obj) {
        System.out.println(obj);
    }

    public static void printArray(Object[] arr) {
        for (Object obj : arr) {
            System.out.println(obj);
        }
    }

    public static void main(String[] args) {
        print("abc");
        print(123);
        print(new Object());
        print(new int[] {1, 2, 3});
        print(new String[] {"a", "b", "c"});
        printArray(new Object[] {1, 2, 3});
        printArray(new int[] {1, 2, 3});
        printArray(new String[] {"a", "b", "c"});
    }
}
