## 2.2.2. Viết lại lời giải

Từ đó, ta có thể viết lại lời giải của chương trình.

```java
import javax.servlet.http.HttpServletResponse;

public class ClassX {
    /**
     * Chuyển hướng người dùng đến một URL mục tiêu.
     * 
     * Hàm này xác thực mục tiêu so với danh sách đen các miền độc hại đã biết.
     */
    public void redirectTo(String url, HttpServletResponse response) {
        // Xác thực mục tiêu
        if (isDangerousUrl(url)) {
            // Nếu mục tiêu là miền độc hại, trả về trang báo lỗi
            response.sendError(HttpServletResponse.SC_FORBIDDEN);
        } else {
            // Nếu mục tiêu không là miền độc hại, chuyển hướng người dùng đến mục tiêu
            response.sendRedirect(url);
        }
    }

    /**
     * Xác thực một URL mục tiêu có phải là miền độc hại hay không.
     */
    private boolean isDangerousUrl(String url) {
        // Kiểm tra từng miền độc hại
        for (String dangerousDomain : dangerousDomains) {
            if (url.startsWith(dangerousDomain)) {
                return true;
            }
        }
        return false;
    }

    private String[] dangerousDomains = {
        "https://bad.com",
        "https://evil.com",
        "https://evil.com/admin",
    };
}
```

