public class FindTheParityOutlier implements Kata {

    public static int find(int[] integers) {
        List<Integer> odds = Arrays.stream(integers).filter(i -> i % 2!= 0).collect(Collectors.toList());
        List<Integer> evens = Arrays.stream(integers).filter(i -> i % 2 == 0).collect(Collectors.toList());

        if (odds.size() == 1) {
