public class XssTool {

	private List<XssRule> xssRules;

	public XssTool(InputStream xssRulesInputStream) throws IOException {
		this(new InputStreamReader(xssRulesInputStream, StandardCharsets.UTF_8));
	}

	public XssTool(Reader xssRulesReader) throws IOException {
		this(IOUtils.toString(xssRulesReader));
	}

	public XssTool(String xssRulesString) {
		this.xssRules = new ArrayList<>();
		for (String line : xssRulesString.split("\n")) {
			if (StringUtils.isBlank(line)) {
				continue;
			}
			if (line.startsWith("#")) {
				continue;
			}

			XssRuleType ruleType = XssRuleType.valueOf(line.toUpperCase().trim());
			if (ruleType == null) {
				continue;
			}

			XssRule xssRule = new XssRule(ruleType);
			String ruleContent = StringUtils.substringAfter(line, ruleType.name());
			xssRule.setRuleContent(ruleContent);
			xssRule.setRuleContentRegex(Pattern.compile(ruleContent));
			xssRules.add(xssRule);
		}
	}

