package br.ufc.quixada.npi.si.gui.util;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.Toolkit;
import java.awt.Window;

/**
 *
 * @author 
 */
public class SwingUtils {

    public static void centerWindow(Window window) {
        Dimension screenSize = Toolkit.getDefaultToolkit().getScreenSize();
        Dimension windowSize = window.getSize();
        if (windowSize.width > screenSize.width) {
            windowSize.width = screenSize.width;
        }
        if (windowSize.height > screenSize.height) {
            windowSize.height = screenSize.height;
        }
        window.setLocation((screenSize.width - windowSize.width) / 2, (screenSize.height - windowSize.height) / 2);
    }

    public static void centerWindow(Component component) {
        Window window = SwingUtils.getWindow(component);
        SwingUtils.centerWindow(window);
    }

    public static Window getWindow(Component component) {
        Window window = null;
        if (component.getParent()!= null) {
            window = SwingUtils.getWindow(component.getParent());
        }
        if (window == null) {
            window = (Window) component;
        }
        return window;
    }

    public static void centerWindow(Container container) {
        SwingUtils.centerWindow(container.getTopLevelAncestor());
    }

    public static void centerPoint(Component component, Point point) {
        Dimension screenSize = Toolkit.getDefaultToolkit().getScreenSize();
        Dimension componentSize = component.getSize();
        component.setLocation(point.x + (screenSize.width - componentSize.width) / 2, point.y + (screenSize.height - componentSize.height) / 2);
    }
}
