import net.dv8tion.jda.api.events.ReadyEvent;
import net.dv8tion.jda.api.events.message.guild.GuildMessageReceivedEvent;
import net.dv8tion.jda.api.hooks.ListenerAdapter;

import javax.security.auth.login.LoginException;
import java.util.logging.Logger;

public class DiscordBot extends ListenerAdapter {

    private static final String BOT_TOKEN = "";

    private static final Logger LOGGER = Logger.getLogger(DiscordBot.class.getName());

    private static JDA jda;

    public static void main(String[] args) throws LoginException {
        jda = new JDABuilder(BOT_TOKEN).build();
        jda.addEventListener(new DiscordBot());
        jda.getPresence().setActivity(Activity.playing("Java"));
        jda.addEventListener(new MessageListener());
    }

    @Override
    public void onReady(ReadyEvent event) {
        LOGGER.info("Logged in as " + jda.getSelfUser().getName());
    }

    @Override
    public void onGuildMessageReceived(GuildMessageReceivedEvent event) {
        if (event.getAuthor().isBot()) {
            return;
        }

        MessageHandler.handleMessage(event);
    }
}
