package hu.bme.mit.train.rail;

import hu.bme.mit.train.interfaces.TrainController;
import hu.bme.mit.train.interfaces.TrainUser;

import java.util.ArrayList;
import java.util.List;

public class Train {
    private TrainController controller;
    private List<TrainUser> users;

    public Train(TrainController controller) {
        this.controller = controller;
        users = new ArrayList<>();
    }

    public void addUser(TrainUser user) {
        users.add(user);
    }

    public void removeUser(TrainUser user) {
        users.remove(user);
    }

    public void move(int direction) {
        controller.moveTrain(direction);
    }

    public void moveTo(int position) {
        controller.moveTo(position);
    }

    public int getPosition() {
        return controller.getPosition();
    }

    public int getDirection() {
        return controller.getDirection();
    }

    public int getSpeed() {
        return controller.getSpeed();
    }

    public boolean isMoving() {
        return controller.isMoving();
    }

    public boolean isAtStation() {
        return controller.isAtStation();
    }

    public int getTrackLength() {
        return controller.getTrackLength();
    }

    public void setSpeed(int speed) {
        controller.setSpeed(speed);
    }

    public void setDirection(int direction) {
        controller.setDirection(direction);
    }

    public void setTrainController(TrainController controller) {
        this.controller = controller;
    }

    public void setUsers(List<TrainUser> users) {
        this.users = users;
    }
}
