import fr.umlv.java.challenge.model.ChallengeServiceImpl;
import fr.umlv.java.challenge.model.ChallengeValidator;
import fr.umlv.java.challenge.model.ChallengeValidatorImpl;

public class ChallengeServer {
    public static void main(String[] args) throws IOException {
        int port = 8080;

        if (args.length > 0) {
            port = Integer.parseInt(args[0]);
        }

        ServerSocket serverSocket = new ServerSocket(port);

        System.out.println("Server started on port " + port);

        ChallengeRepository challengeRepository = new ChallengeRepositoryImpl();
        ChallengeFactory challengeFactory = new ChallengeFactory(challengeRepository);
        ChallengeValidator challengeValidator = new ChallengeValidatorImpl(challengeRepository);
        ChallengeService challengeService = new ChallengeServiceImpl(challengeFactory, challengeValidator);

        ExecutorService executorService = Executors.newFixedThreadPool(10);

        while (true) {
            Socket socket = serverSocket.accept();
            executorService.execute(new ChallengeHandler(socket, challengeService));
        }
    }
}
