import java.util.Objects;

public class Question {
    private final String text;
    private final String[] answers;
    private final String[] correctAnswers;

    public Question(String text, String[] answers, String[] correctAnswers) {
        this.text = text;
        this.answers = answers;
        this.correctAnswers = correctAnswers;
    }

    public String getText() {
        return text;
    }

    public String[] getAnswers() {
        return answers;
    }

    public String[] getCorrectAnswers() {
        return correctAnswers;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass()!= o.getClass()) return false;
        Question question = (Question) o;
        return Objects.equals(text, question.text) &&
                Objects.equals(answers, question.answers) &&
                Objects.equals(correctAnswers, question.correctAnswers);
    }

    @Override
    public int hashCode() {
        return Objects.hash(text, answers, correctAnswers);
    }
}
